// Inserts a note above the length limit and the state_delta reminder. Those two
// lines must stay last, because the model follows the text nearest its reply.
function insertBeforeTail(text, note) {
  var marks = ["\n\n[Hard limit:", "\n\n[Part of your last state_delta", "\n\n[Reminder: end your reply"];
  for (var i = 0; i < marks.length; i++) {
    var at = text.lastIndexOf(marks[i]);
    if (at !== -1) return text.slice(0, at) + "\n\n" + note + text.slice(at);
  }
  return text + "\n\n" + note;
}

// Each complication has one version per stage of the night. The hook picks the
// stage from the milestones, so a complication never asks for a scene the crew
// has already left behind.
var COMPLICATIONS = [
  { label: "the keypad code changes early",
    prep: "Word reaches the crew that the Aurelian will rotate the strongroom keypad code a second time tonight, at 11 pm. Any code taken before then will be stale.",
    job: "The strongroom keypad rejects the first code entered. Security rotated it early tonight, and the panel logs the failed attempt.",
    out: "A service door on the crew's way out now needs a fresh keypad code. Security rotated every code on the building when the night went wrong." },
  { label: "someone is recognized",
    prep: "Colette learns that a dealer she once cheated is on tonight's guest list and will be on the sale floor.",
    job: "A guest on the sale floor recognizes a member of the crew and says their name out loud.",
    out: "A guest leaving the sale photographs a crew member's face, or the crew's vehicle, at close range." },
  { label: "Mr. Quill changes the handoff",
    prep: "Mr. Quill's courier calls. The handoff moves from the ferry terminal to a place Quill will name only at 5 am.",
    job: "Mr. Quill messages in the middle of the job. He wants proof the stone is genuine before he will meet at dawn.",
    out: "Mr. Quill moves the handoff to a new place, an hour earlier, and gives no reason." },
  { label: "a guard swaps shifts",
    prep: "The strongroom guard roster changes. A guard the crew has not studied takes the midnight shift.",
    job: "A guard who swapped shifts at the last minute is on the strongroom level, a person no part of the plan accounts for.",
    out: "A relief guard arrives early for the 6 am shift and walks toward the crew's way out." },
  { label: "the canal police",
    prep: "A canal police patrol boat ties up below the safehouse, and two officers start asking about the shuttered chandlery.",
    job: "A canal police boat idles beside the Aurelian's loading dock, on the crew's side of the building.",
    out: "The canal police stop the crew's vehicle or boat for a routine check." },
  { label: "the timetable moves",
    prep: "Word from the auction staff: the Larkspur Blue goes on the floor ten minutes early, at 12:20.",
    job: "The auctioneer brings the Larkspur Blue up ten minutes early. Every timing the crew built on is now wrong.",
    out: "A staff member checks the strongroom ten minutes before the routine round, so the loss is found sooner than planned." },
  { label: "a second crew",
    prep: "Lev spots another crew scouting the Aurelian's loading dock. Someone else wants the same stone.",
    job: "The crew finds signs of a second crew working the same sale: an unfamiliar tool left in a corridor, a lookout who is not theirs.",
    out: "The second crew that worked the sale is waiting outside, and they want the stone." },
  { label: "the kit fails",
    prep: "A piece of the crew's kit fails its test. A replacement costs money or time.",
    job: "A piece of the crew's kit fails at the worst moment: a radio dies, a battery drains, or a tool snaps.",
    out: "The vehicle for the way out will not start, or one of its tires is flat." },
  { label: "Henrik Aalto moves",
    prep: "Henrik Aalto orders an extra check of the guest list and of every staff entrance for tonight.",
    job: "Henrik Aalto leaves the sale floor and walks toward the strongroom level on a check of his own.",
    out: "Henrik Aalto notices something wrong and starts closing the building's exits one by one." }
];

scripts.context_js:
const modifier = (text) => {
  // Clear the toast first, so a complication message shows on one turn only.
  state.message = "";
  var turn = Math.floor(info.actionCount / 2);
  if (turn < 1 || turn % 3 !== 0) return { text: text };

  // Read only the live state block, so story text cannot match a milestone id.
  var at = text.lastIndexOf("Current world state (running totals");
  var live = at === -1 ? "" : text.slice(at);
  var line = live.match(/\nAchieved: ([^\n]*)/);
  var done = line ? line[1] : "";
  // The engine separates a milestone id from its text with an em dash, char 8212.
  var reached = function (id) {
    return new RegExp("(^|; )" + id + " " + String.fromCharCode(8212)).test(done);
  };
  if (reached("payday")) return { text: text };

  var stage = reached("clean_exit") ? "out" : reached("inside") ? "job" : "prep";
  // Step through the table in an order seeded by the player character, so one
  // adventure never repeats a complication within nine draws. Random draws
  // repeated one entry three times in a playtest. A retry also keeps its draw.
  var p = text.indexOf("Player character:");
  var who = p === -1 ? "" : text.slice(p, p + 200).split("Plot essentials:")[0];
  var seed = 0;
  for (var i = 0; i < who.length; i++) seed = (seed * 31 + who.charCodeAt(i)) % 9973;
  // A stride of 4 is coprime with 9, so nine steps visit every entry once.
  var pick = COMPLICATIONS[(seed + (turn / 3) * 4) % COMPLICATIONS.length];
  var note = "[Complication this turn: " + pick[stage] + " Work it into this scene as a problem the player must answer, and do not solve it for them. If the story is already past this stage of the night, adapt it to where the crew is now.]";
  state.message = "Complication: " + pick.label;
  return { text: insertBeforeTail(text, note) };
};
modifier(text);
